      x.strokeStyle=LIN; x.lineWidth=1; pixRR(x,L,cy,cw,52,12); x.stroke();
      x.fillStyle=INK; x.font="600 15px "+FM; x.textAlign="center"; x.fillText(String(o.linha),L+cw/2,cy+32); x.textAlign="left";
