  var emissaoFmt=pxFmtData(pxDateKey(new Date()));
  var barra=pxDocBarraHtml({ titulo:"Contrato Comercial", codigo:codigo, badge:"Gerado agora", emissao:emissaoFmt, printLabel:"Imprimir / Salvar PDF" });
