      orgData.nodes=orgData.nodes.concat(novos);
      orgClip=orgClip.map(c=>({texto:c.texto,cor:c.cor,forma:c.forma,x:c.x+30,y:c.y+30}));
      orgSel = novos.length===1?novos[0].id:null;
