    var LAY=(czModelo==='deitado')?{cols:1,rows:2,cardL:1}:{A4:{cols:1,rows:1},A5:{cols:1,rows:2,rotCell:1},A6:{cols:2,rows:2},A7:{cols:4,rows:2,land:1}}[czTamanho];
