function czClick(e){
  var t;
  if(t=e.target.closest('[data-cztemadel]')){ e.stopPropagation(); var di=parseInt(t.getAttribute('data-cztemadel'),10); var lt=czTemasGet(); var rem=lt.splice(di,1)[0]; czTemasSave(lt); if(czTema&&rem&&czTema.d===rem.d) czTema=null; renderCartaz(); return; }
  if(t=e.target.closest('[data-cztema]')){ var ti2=parseInt(t.getAttribute('data-cztema'),10); czTema=(ti2<0)?null:(czTemasTodos()[ti2]||null); renderCartaz(); return; }
  if(t=e.target.closest('[data-czmodel]')){ czModelo=t.getAttribute('data-czmodel'); renderCartaz(); return; }
  if(t=e.target.closest('[data-czsize]')){ czTamanho=t.getAttribute('data-czsize'); renderCartaz(); return; }
  if(t=e.target.closest('[data-czdel]')){ czProdutos.splice(parseInt(t.getAttribute('data-czdel'),10),1); renderCartaz(); return; }
  if(t=e.target.closest('[data-czact]')){ var a=t.getAttribute('data-czact');
    if(a==='step1') czStep=1;
    else if(a==='step2') czStep=2;
    else if(a==='step3') czStep=3;
    else if(a==='parse'){ var ta=document.getElementById('czTexto'); czProdutos=czParseTexto(ta?ta.value:''); if(!czProdutos.length){ uiConfirm({titulo:'Lista vazia',msg:'Coloque pelo menos um produto na lista.',ok:'OK',cancel:''}); return; } czStep=3; }
    else if(a==='addrow') czProdutos.push({oferta:'OFERTA',nome:'',marca:'',tipo:'',gram:'',precoDe:'',preco:'',qtd:1});
    else if(a==='gerar'){ if(!czProdutos.length){ uiConfirm({titulo:'Lista vazia',msg:'Nenhum produto na lista.',ok:'OK',cancel:''}); return; } czStep=4; }
    else if(a==='novo'){ czProdutos=[]; czStep=1; czValIni=''; czValidade=''; czLimite='0'; }
    else if(a==='imprimir'){
      if(!czValIni || !czValidade){
        uiConfirm({titulo:'Datas obrigatórias',msg:'Preencha a data de INÍCIO e a data de FIM da oferta antes de imprimir.',ok:'OK',cancel:''});
        [['czValIni',!czValIni],['czValidade',!czValidade]].forEach(function(par){ var el=document.getElementById(par[0]); if(!el) return; if(par[1]){ el.style.borderColor='#e05252'; el.style.boxShadow='0 0 0 3px rgba(224,82,82,.25)'; } else { el.style.borderColor=''; el.style.boxShadow=''; } });
        var _dt=document.getElementById(!czValIni?'czValIni':'czValidade'); if(_dt) _dt.focus();
        return;
      }
      czImprimir(); return; }
    renderCartaz(); return;
  }
}
function czChange(e){ var t=e.target; if(t.id==='czValidade'){ czValidade=t.value; renderCartaz(); } else if(t.id==='czValIni'){ czValIni=t.value; renderCartaz(); } else if(t.id==='czLimite'){ czLimite=t.value; renderCartaz(); } else if(t.name==='czimp'){ czImpressao=t.value; renderCartaz(); } else if(t.id==='czTemaFile'){ czTemaUpload(t); } }
function czInput(e){
  var t=e.target;
  if(t.id==='czTexto'){ var n=t.value.split('\\n').filter(function(x){return x.trim();}).length; var c=document.getElementById('czCount'); if(c) c.textContent=n+' linha(s) detectada(s)'; return; }
  if(t.hasAttribute && t.hasAttribute('data-czfield')){ var idx=parseInt(t.getAttribute('data-czidx'),10); var f=t.getAttribute('data-czfield'); if(czProdutos[idx]) czProdutos[idx][f]=t.value; return; }
}
